/opt/homebrew/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import hashlib
by_hash={}
for path in sorted(Path('evidence').rglob('*')):
    if path.is_file():
        data=path.read_bytes()
        key=hashlib.sha256(data).hexdigest()
        by_hash.setdefault(key,[]).append(str(path))
for key,paths in by_hash.items():
    print(key + ' ' + ', '.join(paths))
